Save the following as main.go. The SQL catalog stores table registrations in SQLite. The Iceberg metadata and Parquet data files go in the local warehouse. package main import ( "context" "fmt" "io" "log" "os" "path/filepath" "github.com/apache/arrow-go/v18/arrow" "github.com/apache/arrow-go/v18/arrow/array" "github.com/apache/arrow-go/v18/arrow/memory" "github.com/apache/iceberg-go" "github.com/apache/iceberg-go/catalog" _ "github.com/apache/iceberg-go/catalog/sql" "github.com/uptrace/bun/driver/sqliteshim"
) func run(ctx context.Context) error { dir, err := os.MkdirTemp("", "iceberg-tutorial-") if err != nil { return err } defer os.RemoveAll(dir) cat, err := catalog.Load(ctx, "tutorial", iceberg.Properties{ "type": "sql", "uri": "file:" + filepath.Join(dir, "catalog.db"), "sql.driver": sqliteshim.ShimName, "sql.dialect": "sqlite", "warehouse": "file://" + filepath.Join(dir, "warehouse"), }) if err != nil { return err } if closer, ok := cat.(io.Closer); ok { defer closer.Close() } if err := cat.CreateNamespace(ctx, catalog.ToIdentifier("taxi"), nil); err != nil { return err } trips := catalog.ToIdentifier("taxi", "trips") schema := iceberg.NewSchema(0, iceberg.NestedField{ID: 1, Name: "trip_id", Type: iceberg.PrimitiveTypes.Int64, Required: true}) tbl, err := cat.CreateTable(ctx, trips, schema) if err != nil { return err } arrowSchema := arrow.NewSchema([]arrow.Field{{Name: "trip_id", Type: arrow.PrimitiveTypes.Int64}}, nil) records := array.NewRecordBuilder(memory.DefaultAllocator, arrowSchema) defer records.Release() records.Field(0).(*array.Int64Builder).AppendValues([]int64{1, 2, 3}, nil) batch := records.NewRecord() defer batch.Release() input := array.NewTableFromRecords(arrowSchema, []arrow.Record{batch}) defer input.Release() tbl, err = tbl.AppendTable(ctx, input, 1024, nil) if err != nil { return err } output, err := tbl.Scan().ToArrowTable(ctx) if err != nil { return err } defer output.Release() if tbl.CurrentSnapshot() == nil || output.NumRows() != 3 { return fmt.Errorf("expected a committed snapshot and 3 rows, got %d rows", output.NumRows()) } fmt.Printf("Read %d rows from taxi.trips and verified a committed snapshot.\n", output.NumRows()) return nil
} func main() { if err := run(context.Background()); err != nil { log.Fatal(err) }
} Run the program: go mod tidy
go run . Read 3 rows from taxi.trips and verified a committed snapshot. The append returns a new table handle with the committed snapshot. The scan uses that handle to read the rows back.

